class Question {
  final int id;
  final String category;
  final String difficulty;
  final String question;
  final List<String> choices;
  final int correct;
  final String explanation;
  final String source;
  final String sourceType;
  final String sourceReference;
  final bool isVerified;
  final String
  reviewStatus; // 'verified' | 'needs_review' | 'draft' | 'rejected'
  final String? sourceUrl;
  final String? reviewerNotes;

  const Question({
    required this.id,
    required this.category,
    required this.difficulty,
    required this.question,
    required this.choices,
    required this.correct,
    required this.explanation,
    this.source = 'المصادر الإسلامية المعتمدة',
    this.sourceType = 'general',
    this.sourceReference = '',
    this.isVerified = true,
    this.reviewStatus = 'verified',
    this.sourceUrl,
    this.reviewerNotes,
  });

  bool get isFullyVerified => isVerified && reviewStatus == 'verified';

  Map<String, dynamic> toJson() => {
    'id': id,
    'category': category,
    'difficulty': difficulty,
    'question': question,
    'choices': choices,
    'correct': correct,
    'explanation': explanation,
    'source': source,
    'sourceType': sourceType,
    'sourceReference': sourceReference,
    'isVerified': isVerified,
    'reviewStatus': reviewStatus,
    if (sourceUrl != null) 'sourceUrl': sourceUrl,
    if (reviewerNotes != null) 'reviewerNotes': reviewerNotes,
  };

  factory Question.fromJson(Map<String, dynamic> json) {
    return Question(
      id: json['id'] as int,
      category: json['category'] as String,
      difficulty: json['difficulty'] as String,
      question: json['question'] as String,
      choices: (json['choices'] as List<dynamic>)
          .map((e) => e.toString())
          .toList(),
      correct: json['correct'] as int,
      explanation: json['explanation'] as String,
      source: json['source'] as String? ?? 'المصادر الإسلامية المعتمدة',
      sourceType: json['sourceType'] as String? ?? 'general',
      sourceReference: json['sourceReference'] as String? ?? '',
      isVerified: json['isVerified'] as bool? ?? true,
      reviewStatus: json['reviewStatus'] as String? ?? 'verified',
      sourceUrl: json['sourceUrl'] as String?,
      reviewerNotes: json['reviewerNotes'] as String?,
    );
  }
}

